/**
 * What each model looks like, and where its page is.
 *
 * Generated by data/build_media.py from the captured portfolio. Do not
 * hand-edit — the mapping of model to page lives in that script, written out
 * by hand, because inferring it put the wrong photograph on a machine.
 *
 * 18 pages, 81 models, 28 KB of inlined thumbnails.
 *
 * `page` is a axim.example URL rather than a path into this repository, so
 * the link works from the preview, the artifact and the deployed app alike.
 */

import { MODEL_PHOTOS } from './photos';
import { VENDOR_MEDIA } from './vendorMedia';
import { VENDOR_DOCS } from './vendorDocs';

export interface ModelMedia {
  /**
   * 88px WebP data URI. Identification at a glance, not a product shot.
   *
   * Null where photo-map.json supplies a real photograph for every model on
   * this page: mediaFor would override it, so shipping it was two images in the
   * bundle and one on the screen.
   */
  thumb: string | null;
  /** The product page on axim.example. */
  page: string;
  /** The primary document's name, where the page offers one. */
  doc: string | null;
  /** Where that document lives. A PDF, unless docKind says otherwise. */
  docUrl: string | null;
  /**
   * What that document IS, so the link can be labelled honestly.
   *
   * REPORTED: a link reading 'datasheet (PDF)' that opened a product page.
   * Some models have only a brochure, and two vendors publish their
   * specification as a web page rather than a PDF; calling all three a
   * datasheet is how a rep ends up sending a customer the wrong thing.
   */
  docKind?: 'datasheet' | 'brochure' | 'specification' | null;
  /** The page's own specification table, deep-linked. */
  specUrl?: string | null;
  /** The brochure, where the page offers one AS WELL AS a datasheet. */
  brochure?: string | null;
  brochureUrl?: string | null;
  /** What Axim calls this on the page. */
  name: string;
  /**
   * 340px WebP, where a real photograph of the machine exists.
   *
   * For the one place a rep has committed to a machine and is looking at it.
   * Absent for a model whose only image is a captured page, because a capture
   * enlarged to 340px is a screenshot of a screenshot.
   */
  hero?: string;
}

