/**
 * Media for a model, or null.
 *
 * Null is a normal answer and not a gap to paper over: most parts in the
 * catalogue are consumables and spares with no model at all, and a model
 * whose page was never captured has nothing honest to show.
 */
export function mediaFor(model: string | null | undefined): ModelMedia | null {
  if (!model) return null;
  /* Machines somebody else publishes.
     A PE311 is a Palisade engine and an K84X is a Kestrel one; both go inside a Axim
     applicator, so neither will ever appear in a capture of axim.example. Sixteen
     quotable parts carried a model, a role of 'printer' and no picture at all.
     Checked first, because for these models there is nothing behind it to fall
     back to. */
  const vendor = VENDOR_MEDIA[model];
  if (vendor) return vendor;
  const slug = MODEL_PAGE[model];
  /* A model-specific document, where the page's own is about the whole range.
     The four Plus-series machines share one page and one combined datasheet; Corvus
     publishes a sheet per machine, and a rep quoting an 6440 wants that one. See
     data/vendor-docs.json. */
  const extra = VENDOR_DOCS[model];
  const page = slug
    ? (extra ? { ...PAGES[slug], ...extra } : PAGES[slug])
    : null;
  /* A real photograph beats a website capture, so where photo-map.json supplies
     one it wins the image. The page link and the datasheet still come from the
     captured portfolio, because a photograph carries neither. */
  const photo = MODEL_PHOTOS[model];
  if (!photo) return page;
  return page
    ? { ...page, thumb: photo.thumb, hero: photo.hero }
    : { thumb: photo.thumb, hero: photo.hero, page: '', doc: null,
        docUrl: null, docKind: null, specUrl: null, name: model };
}
